css:
.nav-cards {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
  gap: 20px;
  margin: 20px 0;
}
.sample-card {
  display: block;
  border-radius: 12px;
  overflow: hidden;
  text-decoration: none;
  color: inherit;
  background: #fff;
  box-shadow: 0 2px 8px rgba(0,0,0,0.08);
  transition: transform 0.2s, box-shadow 0.2s;
}
.sample-card:hover {
  transform: translateY(-6px);
  box-shadow: 0 12px 24px rgba(0,0,0,0.12);
}
.sample-card-thumb {
  position: relative;
  height: 160px;
  background-color: #fff7ed;
  background-size: cover;
  background-position: center;
}
.sample-card-new {
  position: absolute;
  top: 10px;
  left: 10px;
  background: #f97316;
  color: #fff;
  font-size: 0.7rem;
  font-weight: 700;
  padding: 3px 10px;
  border-radius: 999px;
}
.sample-card-new:empty { display: none; }
.sample-card-body { padding: 16px; }
.sample-card-title { margin: 0 0 8px; font-size: 1.1rem; color: #1e293b; }
.sample-card-desc { margin: 0 0 10px; font-size: 0.88rem; color: #64748b; line-height: 1.5; }
.sample-card-date { margin: 0; font-size: 0.75rem; color: #94a3b8; }
.sample-card.active { outline: 2px solid #f97316; }
